Aquí te presento una función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` con el texto en formato HTML:

```cpp
#include <string>
#include <iostream>
#include <regex>

// Función para convertir texto de formato Markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    // Expresión regular para encontrar enlaces Markdown
    std::regex link_regex(R"(^(?:\s|>) *\[(.+?)\]\((.+?)\))");

    // Expresión regular para encontrar código Markdown
    std::regex code_regex(R"(^(`{3}|~{3})[^\n]*\n(?:(?:(?:(?!\n|```).)*\n)+|```[^\n]*\n((?:[^\n]*\n)+?)```))(``{3}|~{3})\n?)");

    std::string html = "<html><body>";
    html += convertMarkdownToHtml(markdown, link_regex, code_regex);
    html += "</body></html>";

    return html;
}

// Función auxiliar para convertir texto de formato Markdown a HTML
std::string convertMarkdownToHtml(const std::string& markdown,
                                  const std::regex& link_regex,
                                  const std::regex& code_regex) {
    std::string html;

    // Reemplazar salto de línea
    std::replace(markdown.begin(), markdown.end(), '\n', '<br>');

    // Reemplazar enlaces Markdown
    std::smatch match;
    if (std::regex_search(markdown, match, link_regex)) {
        std::string link_text = match[1];
        std::string link_url = match[2];
        html += "<a href=\"" + link_url + "\">" + link_text + "</a>";
        markdown.replace(match.position(), match.length(), html);
    }

    // Reemplazar código Markdown
    if (std::regex_search(markdown, match, code_regex)) {
        std::string code = match[2];
        std::string language = match[1].substr(3);
        html = "<pre><code class=\"" + language + "\">" + code + "</code></pre>";
        markdown.replace(match.position(), match.length(), html);
    }

    // Reemplazar otras etiquetas Markdown
    std::replace(markdown.begin(), markdown.end(), '*', '<strong>');
    std::replace(markdown.begin(), markdown.end(), '*', '</strong>');
    std::replace(markdown.begin(), markdown.end(), '_', '<em>');
    std::replace(markdown.begin(), markdown.end(), '_', '</em>');
    std::replace(markdown.begin(), markdown.end(), '#', '<h1>');
    std::replace(markdown.begin(), markdown.end(), '#', '</h1>');
    std::replace(markdown.begin(), markdown.end(), '##', '<h2>');
    std::replace(markdown.begin(), markdown.end(), '##', '</h2>');
    std::replace(markdown.begin(), markdown.end(), '###', '<h3>');
    std::replace(markdown.begin(), markdown.end(), '###', '</h3>');
    std::replace(markdown.begin(), markdown.end(), '####', '<h4>');
    std::replace(markdown.begin(), markdown.end(), '####', '</h4>');
    std::replace(markdown.begin(), markdown.end(), '#####', '<h5>');
    std::replace(markdown.begin(), markdown.end(), '#####', '</h5>');
    std::replace(markdown.begin(), markdown.end(), '######', '<h6>');
    std::replace(markdown.begin(), markdown.end(), '######', '</h6>');

    return html;
}

int main() {
    std::string markdown = "Hello, *world*! [Google](https://google.com/) is a great search engine. Here's some code: ```cpp\n#include <iostream>\nint main() { std::cout << \"Hello, world!\" << std::endl; }\n```";

    std::string html = markdownToHtml(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Esta función utiliza expresiones regulares para detectar enlaces y código Markdown y los reemplaza por etiquetas HTML correspondientes. También reemplaza algunos caracteres comunes en Markdown por sus etiquetas HTML equivalentes.

Recuerda que esta función es solo una aproximación simplificada de la conversión de Markdown a HTML. Para una implementación completa, puedes consultar bibliotecas existentes como `puglert`, `doxygen`, o `Markdown::Parser` para C++.

Espero que esto te sea útil!

