2. Declara la función que leerá el archivo línea por línea y contarán las apariciones de la palabra específica:

```cpp
void countWordOccurrences(std::string filename, std::string word) {
    std::ifstream file(filename); // Abrir el archivo para lectura
    std::string line;
    int occurrences = 0;

    if (!file.is_open()) { // Comprobar si se abrió correctamente el archivo
        std::cerr << "Error: No se pudo abrir el archivo " << filename << std::endl;
        return;
    }

    while (getline(file, line)) { // Leer línea por línea
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) { // Buscar la palabra específica en la línea
            occurrences++; // Incrementar el conteo
            pos++; // Avanzar en la línea para evitar contar la misma aparición nuevamente
        }
    }

    file.close(); // Cerrar el archivo

    std::cout << "El número de apariciones de \"" << word << "\" en " << filename << " es: " << occurrences << std::endl;
}
```

